using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must explicitly preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|KeyValue" to just "KeyValue".
            // Existing documents use "Blog|1" format, so we must opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws in EF Core 9 instead of being silently ignored.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Breaking change 4: EF Core 9 uses sync-over-async only with an explicit opt-in.
    // Cosmos provider now throws on synchronous operations by default.
    // See SyncJob.cs for the fix (switch to async APIs).
}

