arguments.new_str:
class SyncJob
{
    // Breaking change 4: Cosmos provider in EF Core 9 throws
    // InvalidOperationException on synchronous calls (ToList, SaveChanges).
    // Must use async APIs instead.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

