using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must explicitly preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|KeyValue"
            // to just "KeyValue". Use IdProperty convention to keep legacy format.
            entity.Property<string>("__id")
                .ToJsonProperty("id");
            entity.HasKey("__id");

            // Breaking change 3: HasIndex() now throws at runtime for Cosmos provider
            // instead of being silently ignored. Remove all HasIndex calls.
            // (Removed: entity.HasIndex(b => b.Name))
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Example connection — replace with your actual config
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "BlogDb");
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

